import React, { useState, useEffect } from 'react';
import './App.css';

const API_BASE = 'http://localhost:5000/api/user';

function App() {
  // ===== CORE STATE =====
  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState(new Set());
  const [formData, setFormData] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const [responseMessage, setResponseMessage] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);
  const [errorDetails, setErrorDetails] = useState('');
  const [smsConversation, setSmsConversation] = useState([]);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [phoneNumber, setPhoneNumber] = useState('');
  const [serverStatus, setServerStatus] = useState('checking');
  const [activationDone, setActivationDone] = useState(false);
  const [showRegistrationComplete, setShowRegistrationComplete] = useState(false);

  // ===== DASHBOARD STATE =====
  const [allMatches, setAllMatches] = useState([]);
  const [currentMatchIndex, setCurrentMatchIndex] = useState(0);
  const [incomingRequests, setIncomingRequests] = useState([]);
  const [myMatches, setMyMatches] = useState([]);
  const [chatMessages, setChatMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [activeChatUser, setActiveChatUser] = useState(null);
  const [activeTab, setActiveTab] = useState('discover');
  const [showProfile, setShowProfile] = useState(false);
  const [showMatchDetails, setShowMatchDetails] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState(null);

  // ============================================
  // SAMPLE DATA
  // ============================================

  const SAMPLE_MATCHES = [
    { 
      id: 1,
      phone: '0722010203', 
      name: 'Lina Moraa', 
      age: 29, 
      town: 'Nairobi', 
      county: 'Nairobi County',
      profession: 'Nurse', 
      education: 'Graduate', 
      religion: 'Christian', 
      ethnicity: 'Kikuyu', 
      marital_status: 'single',
      description: 'Kind-hearted and adventurous. Loves hiking and reading. I enjoy long walks on the beach and sunset views.',
      status: 'pending'
    },
    { 
      id: 2,
      phone: '0701223344', 
      name: 'Dorine Gakii', 
      age: 26, 
      town: 'Nakuru', 
      county: 'Nakuru County',
      profession: 'Teacher', 
      education: 'Diploma', 
      religion: 'Christian', 
      ethnicity: 'Kamba', 
      marital_status: 'single',
      description: 'Caring and dedicated. Loves children and education. I believe in making a difference in young lives.',
      status: 'pending'
    },
    { 
      id: 3,
      phone: '0700112233', 
      name: 'Aisha Bahati', 
      age: 27, 
      town: 'Mombasa', 
      county: 'Mombasa County',
      profession: 'Accountant', 
      education: 'Graduate', 
      religion: 'Muslim', 
      ethnicity: 'Swahili', 
      marital_status: 'single',
      description: 'Ambitious and hardworking. I love numbers and helping people manage their finances wisely.',
      status: 'pending'
    },
    { 
      id: 4,
      phone: '0722040506', 
      name: 'Pamela Nafula', 
      age: 26, 
      town: 'Kisumu', 
      county: 'Kisumu County',
      profession: 'Engineer', 
      education: 'Post Graduate', 
      religion: 'Christian', 
      ethnicity: 'Luo', 
      marital_status: 'single',
      description: 'Tech enthusiast. Loves innovation and building solutions that change lives.',
      status: 'pending'
    },
    { 
      id: 5,
      phone: '0702556677', 
      name: 'Maria Mwende', 
      age: 28, 
      town: 'Kasarani', 
      county: 'Nairobi County',
      profession: 'Nurse', 
      education: 'Graduate', 
      religion: 'Christian', 
      ethnicity: 'Kamba', 
      marital_status: 'single',
      description: 'Diligent, loving, dedicated and will make you tick. I love caring for others.',
      status: 'pending'
    },
    { 
      id: 6,
      phone: '0708990011', 
      name: 'Keziah Cheptab', 
      age: 28, 
      town: 'Eldoret', 
      county: 'Uasin Gishu County',
      profession: 'Doctor', 
      education: 'Post Graduate', 
      religion: 'Christian', 
      ethnicity: 'Kalenjin', 
      marital_status: 'single',
      description: 'Passionate about healthcare and community service. I love helping others.',
      status: 'pending'
    }
  ];

  const SAMPLE_REQUESTS = [
    { id: 101, name: 'Michael Ochieng', age: 30, town: 'Nairobi', phone: '0723000001', message: '💕 Shows interest in you', status: 'pending' },
    { id: 102, name: 'David Kiprop', age: 28, town: 'Eldoret', phone: '0723000002', message: '💕 Shows interest in you', status: 'pending' }
  ];

  const SAMPLE_MY_MATCHES = [
    { id: 201, name: 'Grace Akinyi', age: 27, town: 'Kisumu', phone: '0724000001', status: 'accepted' },
    { id: 202, name: 'Peter Mwangi', age: 29, town: 'Nakuru', phone: '0724000002', status: 'accepted' }
  ];

  const SAMPLE_CHAT = [
    { id: 1, sender: 'Grace Akinyi', message: 'Hi there! How are you?', time: '10:30 AM', isMine: false },
    { id: 2, sender: 'You', message: 'I\'m great! How about you?', time: '10:32 AM', isMine: true },
    { id: 3, sender: 'Grace Akinyi', message: 'I\'m doing well. Would you like to meet up?', time: '10:35 AM', isMine: false }
  ];

  // ============================================
  // STEPS DEFINITION
  // ============================================

  const STEPS = [
    {
      id: 1,
      title: 'Service Activation',
      subtitle: 'Send PENZI to activate',
      icon: '💑',
      endpoint: '/activate',
      method: 'POST',
      fields: [{ key: 'penzi', label: 'Enter Activation Code', placeholder: 'Type PENZI', type: 'text' }],
      buildBody: (data) => ({ penzi: data.penzi || 'penzi' }),
      isActivation: true,
      userMessage: 'PENZI',
      systemMessage: 'Welcome to our dating service with 6000 potential dating partners! To register SMS start#name#age#gender#county#town to 22141. E.g., start#John Doe#26#Male#Nakuru#Naivasha'
    },
    {
      id: 2,
      title: 'Service Registration',
      subtitle: 'Create your account',
      icon: '📝',
      endpoint: '/register',
      method: 'POST',
      fields: [
        { key: 'phone_number', label: '📱 Phone Number', placeholder: '0712345678', type: 'tel' },
        { key: 'name', label: '👤 Full Name', placeholder: 'John Doe', type: 'text' },
        { key: 'age', label: '🎂 Age', placeholder: '26', type: 'number' },
        { key: 'gender', label: '⚤ Gender', type: 'select', options: ['Male', 'Female', 'Other'] },
        { key: 'county', label: '📍 County', placeholder: 'Nakuru', type: 'text' },
        { key: 'town', label: '🏙️ Town/City', placeholder: 'Naivasha', type: 'text' }
      ],
      buildBody: (data) => ({
        phone_number: data.phone_number,
        name: data.name,
        age: data.age,
        gender: data.gender,
        county: data.county,
        town: data.town
      }),
      userMessage: (data) => `start#${data.name}#${data.age}#${data.gender}#${data.county}#${data.town}`,
      systemMessage: (data) => `Your profile has been created successfully ${data.name}. SMS details#levelOfEducation#profession#maritalStatus#religion#ethnicity to 22141.`
    },
    {
      id: 3,
      title: 'Details Registration',
      subtitle: 'Complete your profile',
      icon: '📋',
      endpoint: '/{phone}/complete-profile',
      method: 'POST',
      fields: [
        { key: 'education_level', label: '🎓 Education Level', type: 'select', options: ['Primary', 'Secondary', 'Certificate', 'Diploma', 'Graduate', 'Post Graduate'] },
        { key: 'profession', label: '💼 Profession', placeholder: 'Accountant', type: 'text' },
        { key: 'marital_status', label: '💍 Marital Status', type: 'select', options: ['single', 'married', 'divorced', 'widowed', 'separated'] },
        { key: 'religion', label: '⛪ Religion', placeholder: 'Christian', type: 'text' },
        { key: 'ethnicity', label: '🌍 Ethnicity', placeholder: 'Kikuyu', type: 'text' }
      ],
      requiresPhone: true,
      buildBody: (data) => ({
        education_level: data.education_level,
        profession: data.profession,
        marital_status: data.marital_status,
        religion: data.religion,
        ethnicity: data.ethnicity
      }),
      userMessage: (data) => `details#${data.education_level}#${data.profession}#${data.marital_status}#${data.religion}#${data.ethnicity}`,
      systemMessage: 'This is the last stage of registration. SMS a brief description of yourself to 22141 starting with the word MYSELF.'
    },
    {
      id: 4,
      title: 'Self-Description',
      subtitle: 'Tell us about yourself',
      icon: '💭',
      endpoint: '/{phone}/self-description',
      method: 'POST',
      fields: [{ key: 'description', label: 'Describe yourself', placeholder: 'Hardworking, honest, family-oriented...', type: 'textarea' }],
      requiresPhone: true,
      buildBody: (data) => ({ description: data.description }),
      userMessage: (data) => `MYSELF ${data.description}`,
      systemMessage: 'You are now registered for dating! To search for a MPENZI, SMS match#age#town to 22141.'
    },
    {
      id: 5,
      title: 'Matching Request',
      subtitle: 'Search for your match',
      icon: '❤️',
      endpoint: '/sms',
      method: 'POST',
      fields: [
        { key: 'age_range', label: '📅 Age Range', placeholder: '26-30', type: 'text' },
        { key: 'town', label: '📍 Town/City', placeholder: 'Nairobi', type: 'text' }
      ],
      requiresPhone: true,
      buildBody: (data) => ({
        phone_number: data.phone_number,
        message: `match#${data.age_range}#${data.town}`
      }),
      userMessage: (data) => `match#${data.age_range}#${data.town}`,
      isFinal: true
    }
  ];

  // ============================================
  // LOAD SAVED STATE
  // ============================================

  useEffect(() => {
    try {
      const saved = localStorage.getItem('penziState');
      if (saved) {
        const parsed = JSON.parse(saved);
        setCurrentStep(parsed.currentStep || 0);
        setCompletedSteps(new Set(parsed.completedSteps || []));
        setSmsConversation(parsed.smsConversation || []);
        setPhoneNumber(parsed.phoneNumber || '');
        setActivationDone(parsed.activationDone || false);
        setAllMatches(parsed.allMatches || SAMPLE_MATCHES);
        setIncomingRequests(parsed.incomingRequests || SAMPLE_REQUESTS);
        setMyMatches(parsed.myMatches || SAMPLE_MY_MATCHES);
        setChatMessages(parsed.chatMessages || SAMPLE_CHAT);
        setActiveTab(parsed.activeTab || 'discover');
        if (parsed.currentUser) {
          setCurrentUser(parsed.currentUser);
          setIsLoggedIn(true);
        }
      } else {
        // Initialize with sample data
        setAllMatches(SAMPLE_MATCHES);
        setIncomingRequests(SAMPLE_REQUESTS);
        setMyMatches(SAMPLE_MY_MATCHES);
        setChatMessages(SAMPLE_CHAT);
      }
    } catch (e) {
      console.warn('Could not load saved state:', e);
      setAllMatches(SAMPLE_MATCHES);
      setIncomingRequests(SAMPLE_REQUESTS);
      setMyMatches(SAMPLE_MY_MATCHES);
      setChatMessages(SAMPLE_CHAT);
    }
  }, []);

  // ============================================
  // SAVE STATE
  // ============================================

  useEffect(() => {
    try {
      const stateToSave = {
        currentStep,
        completedSteps: Array.from(completedSteps),
        smsConversation,
        currentUser,
        phoneNumber,
        activationDone,
        allMatches,
        incomingRequests,
        myMatches,
        chatMessages,
        activeTab
      };
      localStorage.setItem('penziState', JSON.stringify(stateToSave));
    } catch (e) {
      console.warn('Could not save state:', e);
    }
  }, [currentStep, completedSteps, smsConversation, currentUser, phoneNumber, activationDone, allMatches, incomingRequests, myMatches, chatMessages, activeTab]);

  // ============================================
  // CHECK SERVER
  // ============================================

  useEffect(() => {
    checkServer();
  }, []);

  const checkServer = async () => {
    try {
      const response = await fetch(`${API_BASE}/activate`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ penzi: 'penzi' })
      });
      if (response.ok || response.status === 400 || response.status === 405) {
        setServerStatus('connected');
      } else {
        setServerStatus('error');
      }
    } catch (error) {
      setServerStatus('error');
    }
  };

  // ============================================
  // HELPERS
  // ============================================

  const handleInputChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const addToConversation = (sender, message, isSystem = false) => {
    const entry = {
      id: Date.now(),
      sender: sender,
      message: message,
      isSystem: isSystem,
      timestamp: new Date().toLocaleTimeString()
    };
    setSmsConversation(prev => [...prev, entry]);
  };

  const addNotification = (message, type = 'success') => {
    const id = Date.now();
    setNotifications(prev => [...prev, { id, message, type }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 5000);
  };

  const getProgress = () => {
    if (!activationDone) return 0;
    return Math.round((completedSteps.size / STEPS.length) * 100);
  };

  const goToStep = (index) => {
    if (index >= 0 && index < STEPS.length) {
      setCurrentStep(index);
    }
  };

  // ============================================
  // DISCOVER FUNCTIONS
  // ============================================

  const viewProfile = (match) => {
    setSelectedMatch(match);
    setShowMatchDetails(true);
  };

  const expressInterest = (match) => {
    // Add to conversation
    addToConversation('📱 You', `Expressing interest in ${match.name}`, false);
    addToConversation('🤖 System', `💕 Interest sent to ${match.name}! They will be notified.`, true);

    // Add to incoming requests
    const newRequest = {
      id: Date.now(),
      name: match.name,
      age: match.age,
      town: match.town,
      phone: match.phone,
      message: `💕 ${currentUser?.name || 'Someone'} is interested in you!`,
      status: 'pending'
    };
    setIncomingRequests(prev => [...prev, newRequest]);

    // Remove from available matches
    setAllMatches(prev => prev.filter(m => m.phone !== match.phone));

    addNotification(`💕 Interest sent to ${match.name}!`);
  };

  // ============================================
  // REQUEST FUNCTIONS
  // ============================================

  const acceptRequest = (request) => {
    const newMatch = {
      id: Date.now(),
      name: request.name,
      age: request.age,
      town: request.town,
      phone: request.phone,
      status: 'accepted'
    };
    setMyMatches(prev => [...prev, newMatch]);
    setIncomingRequests(prev => prev.filter(r => r.id !== request.id));
    addNotification(`✅ You accepted ${request.name}'s request!`);
    addToConversation('📱 You', `Accepted ${request.name}'s interest`, false);
    addToConversation('🤖 System', `✅ You are now matched with ${request.name}!`, true);
  };

  const declineRequest = (request) => {
    setIncomingRequests(prev => prev.filter(r => r.id !== request.id));
    addNotification(`❌ You declined ${request.name}'s request.`);
  };

  // ============================================
  // CHAT FUNCTIONS
  // ============================================

  const sendMessage = () => {
    if (!newMessage.trim() || !activeChatUser) return;

    const message = {
      id: Date.now(),
      sender: 'You',
      message: newMessage,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isMine: true
    };

    setChatMessages(prev => [...prev, message]);
    setNewMessage('');

    // Auto-reply
    setTimeout(() => {
      const replies = [
        "That's great to hear! 😊",
        "I totally agree with you!",
        "Tell me more about that.",
        "That's interesting!",
        "I'd love to know more.",
        "Sounds wonderful!",
        "Yes, I think so too.",
        "That's a great idea!",
        "I'm looking forward to it.",
        "That makes sense."
      ];
      const reply = {
        id: Date.now() + 1,
        sender: activeChatUser.name,
        message: replies[Math.floor(Math.random() * replies.length)],
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        isMine: false
      };
      setChatMessages(prev => [...prev, reply]);
    }, 1000);
  };

  const startChat = (match) => {
    setActiveChatUser(match);
    setActiveTab('chat');
  };

  // ============================================
  // BUILD SMS PREVIEW
  // ============================================

  const buildSmsPreview = (step) => {
    if (step.id === 1) return 'PENZI';
    if (step.id === 2) {
      return `start#${formData.name || 'John Doe'}#${formData.age || '26'}#${formData.gender || 'Male'}#${formData.county || 'Nakuru'}#${formData.town || 'Naivasha'}`;
    }
    if (step.id === 3) {
      return `details#${formData.education_level || 'diploma'}#${formData.profession || 'driver'}#${formData.marital_status || 'single'}#${formData.religion || 'christian'}#${formData.ethnicity || 'mijikenda'}`;
    }
    if (step.id === 4) {
      return `MYSELF ${formData.description || 'Your description here'}`;
    }
    if (step.id === 5) {
      return `match#${formData.age_range || '26-30'}#${formData.town || 'Nairobi'}`;
    }
    return '';
  };

  // ============================================
  // EXECUTE API
  // ============================================

  const executeApi = async () => {
    const step = STEPS[currentStep];
    setIsLoading(true);
    setResponseMessage('');
    setIsSuccess(false);
    setErrorDetails('');

    try {
      let phone = formData.phone_number || phoneNumber || '0712345678';

      let endpoint = step.endpoint;
      if (step.requiresPhone) {
        endpoint = endpoint.replace('{phone}', phone);
      }

      const fullUrl = API_BASE + endpoint;
      console.log(`📡 Calling: ${step.method} ${fullUrl}`);

      let body = null;
      if (step.buildBody) {
        body = step.buildBody(formData);
        if (step.requiresPhone && !body.phone_number) {
          body.phone_number = phone;
        }
      }

      const options = {
        method: step.method,
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        }
      };

      if (body && (step.method === 'POST' || step.method === 'PUT')) {
        options.body = JSON.stringify(body);
      }

      const response = await fetch(fullUrl, options);
      console.log(`📥 Status: ${response.status}`);

      let responseData;
      const contentType = response.headers.get('content-type');
      if (contentType && contentType.includes('application/json')) {
        responseData = await response.json();
      } else {
        responseData = await response.text();
      }

      console.log('📥 Response:', responseData);

      if (response.ok) {
        // STEP 1: ACTIVATION
        if (step.id === 1) {
          const welcomeMsg = responseData?.message || step.systemMessage;
          addToConversation('📱 You', 'PENZI', false);
          addToConversation('🤖 System', welcomeMsg, true);
          setActivationDone(true);
          setResponseMessage('✅ Service activated successfully!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Service activated! Proceed to registration.');
          setPhoneNumber('0712345678');
        }
        // STEP 2: REGISTRATION
        else if (step.id === 2) {
          const userMsg = step.userMessage(formData);
          const sysMsg = step.systemMessage(formData);
          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setPhoneNumber(formData.phone_number || '0712345678');
          setResponseMessage('✅ Registration complete!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete! Proceed to step 3.');
        }
        // STEP 3: DETAILS
        else if (step.id === 3) {
          const userMsg = step.userMessage(formData);
          const sysMsg = step.systemMessage;
          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setResponseMessage('✅ Profile completed!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Profile completed! Proceed to step 4.');
        }
        // STEP 4: SELF-DESCRIPTION
        else if (step.id === 4) {
          const userMsg = step.userMessage(formData);
          const sysMsg = step.systemMessage;
          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setResponseMessage('✅ Registration complete!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete! Proceed to step 5.');
        }
        // STEP 5: MATCHING
        else if (step.id === 5) {
          const userMsg = step.userMessage(formData);
          addToConversation('📱 You', userMsg, false);

          const countMsg = `We have ${allMatches.length} ladies who match your choice!`;
          addToConversation('🤖 System', countMsg, true);

          const firstThree = allMatches.slice(0, 3);
          firstThree.forEach(m => {
            addToConversation('🤖 System', `${m.name} aged ${m.age}, ${m.phone}.`, true);
          });

          if (allMatches.length > 3) {
            addToConversation('🤖 System', `Send NEXT to 22141 to receive details of the remaining ${allMatches.length - 3} ladies`, true);
          }

          setResponseMessage(`✅ Found ${allMatches.length} matches!`);
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));

          const user = {
            phone: formData.phone_number || phone || '0712345678',
            name: formData.name || 'User',
            age: formData.age || '26',
            town: formData.town || 'Nairobi'
          };
          setCurrentUser(user);
          setShowRegistrationComplete(true);

          // After a short delay, go to dashboard
          setTimeout(() => {
            setIsLoggedIn(true);
            addNotification(`🎉 Welcome to PENZI! You have ${allMatches.length} matches!`);
          }, 1500);
        }
      } else {
        const errorMsg = responseData?.message || responseData?.error || `Error ${response.status}`;
        setResponseMessage('❌ ' + errorMsg);
        setIsSuccess(false);
        setErrorDetails(`Status: ${response.status}`);
        addNotification(`❌ ${errorMsg}`, 'error');
      }
    } catch (error) {
      console.error('❌ API Error:', error);
      let errorMessage = 'Network Error';
      let errorDetail = '';
      if (error.message.includes('Failed to fetch')) {
        errorMessage = 'Cannot connect to the server.';
        errorDetail = `Make sure the backend is running at ${API_BASE}`;
      } else {
        errorMessage = error.message || 'An unknown error occurred.';
        errorDetail = 'Please check your connection and try again.';
      }
      setResponseMessage('❌ ' + errorMessage);
      setIsSuccess(false);
      setErrorDetails(errorDetail);
      addNotification(`❌ ${errorMessage}`, 'error');
    } finally {
      setIsLoading(false);
    }
  };

  // ============================================
  // RENDER SMS CONVERSATION
  // ============================================

  const renderSmsConversation = () => {
    if (smsConversation.length === 0) return null;
    return (
      <div className="sms-conversation-container">
        <div className="sms-conversation-header">
          <span className="conversation-title">💬 SMS Conversation</span>
          <span className="conversation-count">{smsConversation.length} messages</span>
        </div>
        <div className="sms-conversation">
          {smsConversation.map((msg) => (
            <div key={msg.id} className={`sms-conversation-bubble ${msg.isSystem ? 'system' : 'user'}`}>
              <div className="sms-sender">{msg.sender}</div>
              <div className="sms-message">{msg.message}</div>
              <div className="sms-time">{msg.timestamp}</div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER REGISTRATION
  // ============================================

  const renderRegistration = () => {
    const step = STEPS[currentStep];
    const isFirstStep = currentStep === 0;
    const isLastStep = currentStep === STEPS.length - 1;
    const previewSms = buildSmsPreview(step);
    const isActivationStep = step.id === 1;

    return (
      <div className="registration-container">
        <div className="registration-card">
          <div className="registration-header">
            <div className="registration-icon">{step.icon}</div>
            <h1>PENZI Dating</h1>
            <p className="subtitle">Find your perfect match</p>
          </div>

          <div className={`server-status ${serverStatus}`}>
            <span className="status-dot"></span>
            <span className="status-text">
              {serverStatus === 'connected' ? '✅ Server Connected' : 
               serverStatus === 'checking' ? '⏳ Checking...' : 
               '❌ Server Not Connected'}
            </span>
          </div>

          {activationDone && (
            <div className="progress-bar-container">
              <div className="progress-bar">
                <div className="progress-fill" style={{ width: `${getProgress()}%` }}></div>
              </div>
              <span className="progress-text">{getProgress()}% Complete • {completedSteps.size}/{STEPS.length}</span>
            </div>
          )}

          {renderSmsConversation()}

          <div className="step-info-card">
            <div className="step-number">
              {isActivationStep ? '🔑 ENTRY POINT' : `Step ${currentStep + 1} of ${STEPS.length}`}
            </div>
            <h2>{step.title}</h2>
            <p>{step.subtitle}</p>
          </div>

          <form onSubmit={(e) => { e.preventDefault(); executeApi(); }} className="registration-form">

            {isActivationStep && (
              <div className="activation-hint">
                <div className="hint-bubble">
                  <span className="hint-label">📱 To activate:</span>
                  <span className="hint-code">PENZI</span>
                </div>
              </div>
            )}

            {step.requiresPhone && !isActivationStep && (
              <div className="input-group">
                <label>📱 Your Phone Number</label>
                <input
                  type="text"
                  value={formData.phone_number || phoneNumber || ''}
                  onChange={(e) => handleInputChange('phone_number', e.target.value)}
                  placeholder="Enter your phone number"
                  className="input-field"
                  required
                />
              </div>
            )}

            {step.fields && step.fields.map((field) => (
              <div key={field.key} className="input-group">
                <label>{field.label}</label>
                {field.type === 'select' ? (
                  <select
                    value={formData[field.key] || ''}
                    onChange={(e) => handleInputChange(field.key, e.target.value)}
                    className="input-field"
                    required
                  >
                    <option value="">Select {field.label}</option>
                    {field.options.map(opt => (
                      <option key={opt} value={opt}>{opt}</option>
                    ))}
                  </select>
                ) : field.type === 'textarea' ? (
                  <textarea
                    value={formData[field.key] || ''}
                    onChange={(e) => handleInputChange(field.key, e.target.value)}
                    placeholder={field.placeholder}
                    className="textarea-field"
                    rows={3}
                    required
                  />
                ) : (
                  <input
                    type={field.type || 'text'}
                    value={formData[field.key] || ''}
                    onChange={(e) => handleInputChange(field.key, e.target.value)}
                    placeholder={field.placeholder}
                    className="input-field"
                    required
                  />
                )}
              </div>
            ))}

            {previewSms && (
              <div className="sms-preview-container">
                <div className="sms-preview-label">📱 Your SMS will be:</div>
                <div className="sms-preview-content">{previewSms}</div>
              </div>
            )}

            <div className="registration-actions">
              <button
                type="button"
                onClick={() => goToStep(currentStep - 1)}
                disabled={currentStep === 0 || isLoading || !activationDone}
                className="btn-secondary"
              >
                ⬅ Previous
              </button>

              <button
                type="submit"
                disabled={isLoading || serverStatus === 'error'}
                className={`btn-primary ${isLoading ? 'loading' : ''}`}
              >
                {isLoading ? '⏳ Sending...' : isActivationStep ? '💑 Activate Service' : '📤 Send SMS'}
              </button>

              <button
                type="button"
                onClick={() => goToStep(currentStep + 1)}
                disabled={isLastStep || isLoading || !completedSteps.has(currentStep)}
                className="btn-secondary"
              >
                Next ➡
              </button>
            </div>
          </form>

          {errorDetails && (
            <div className="error-details">
              <p className="error-detail-text">💡 {errorDetails}</p>
            </div>
          )}

          {responseMessage && (
            <div className={`response-message ${isSuccess ? 'success' : 'error'}`}>
              {responseMessage}
            </div>
          )}

          {/* Registration Complete Screen */}
          {showRegistrationComplete && (
            <div className="registration-complete">
              <div className="complete-icon">🎉</div>
              <h2>Registration Complete!</h2>
              <p>Welcome to PENZI Dating, {currentUser?.name}!</p>
              <p style={{ fontSize: '13px', color: '#6b7280' }}>You have {allMatches.length} potential matches waiting for you.</p>
              <button 
                className="btn-primary" 
                style={{ marginTop: '16px', width: '100%' }}
                onClick={() => setIsLoggedIn(true)}
              >
                Go to Dashboard →
              </button>
            </div>
          )}

          <div className="registration-footer">
            <p>🔒 Your data is safe and private</p>
          </div>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER NOTIFICATIONS
  // ============================================

  const renderNotifications = () => {
    if (notifications.length === 0) return null;
    return (
      <div className="notifications-container">
        {notifications.map((notif) => (
          <div key={notif.id} className={`notification ${notif.type || 'success'}`}>
            {notif.message}
          </div>
        ))}
      </div>
    );
  };

  // ============================================
  // RENDER DASHBOARD
  // ============================================

  const renderDashboard = () => {
    const currentMatch = allMatches[currentMatchIndex] || allMatches[0];
    const hasMatches = allMatches.length > 0;
    const hasRequests = incomingRequests.length > 0;
    const hasMyMatches = myMatches.length > 0;

    return (
      <div className="dashboard-container">
        {/* Header */}
        <header className="dashboard-header">
          <div className="header-left">
            <h1>💑 PENZI</h1>
            <span className="live-badge">❤️ Live</span>
          </div>
          <div className="header-right">
            <span className="user-greeting">👋 {currentUser?.name || 'User'}</span>
            <button className="profile-btn" onClick={() => setShowProfile(!showProfile)}>👤</button>
          </div>
        </header>

        {/* Navigation */}
        <nav className="dashboard-nav">
          <button 
            className={`nav-item ${activeTab === 'discover' ? 'active' : ''}`} 
            onClick={() => setActiveTab('discover')}
          >
            🔍 Discover
            <span className="nav-badge">{allMatches.length}</span>
          </button>
          <button 
            className={`nav-item ${activeTab === 'matches' ? 'active' : ''}`} 
            onClick={() => setActiveTab('matches')}
          >
            💕 Matches
            <span className="nav-badge">{myMatches.length}</span>
          </button>
          <button 
            className={`nav-item ${activeTab === 'requests' ? 'active' : ''}`} 
            onClick={() => setActiveTab('requests')}
          >
            📬 Requests
            {hasRequests && <span className="nav-badge red">{incomingRequests.length}</span>}
          </button>
          <button 
            className={`nav-item ${activeTab === 'chat' ? 'active' : ''}`} 
            onClick={() => setActiveTab('chat')}
          >
            💬 Chat
            {chatMessages.length > 0 && <span className="nav-badge">{chatMessages.length}</span>}
          </button>
        </nav>

        {/* Content */}
        <main className="dashboard-content">

          {/* ===== DISCOVER TAB ===== */}
          {activeTab === 'discover' && (
            <div className="discover-container">
              {hasMatches ? (
                <div className="match-card">
                  <div className="match-card-header">
                    <div className="match-avatar">{currentMatch?.name?.charAt(0) || '?'}</div>
                    <div className="match-info">
                      <h3>{currentMatch?.name || 'Unknown'}</h3>
                      <p>{currentMatch?.age || '?'} years • {currentMatch?.town || 'Unknown'}</p>
                    </div>
                  </div>

                  <div className="match-details">
                    <div className="detail-item">
                      <span className="detail-label">💼 Profession</span>
                      <span className="detail-value">{currentMatch?.profession || 'Not specified'}</span>
                    </div>
                    <div className="detail-item">
                      <span className="detail-label">🎓 Education</span>
                      <span className="detail-value">{currentMatch?.education || 'Not specified'}</span>
                    </div>
                    <div className="detail-item">
                      <span className="detail-label">🙏 Religion</span>
                      <span className="detail-value">{currentMatch?.religion || 'Not specified'}</span>
                    </div>
                    <div className="detail-item">
                      <span className="detail-label">🌍 Ethnicity</span>
                      <span className="detail-value">{currentMatch?.ethnicity || 'Not specified'}</span>
                    </div>
                    {currentMatch?.description && (
                      <div className="detail-item full-width">
                        <span className="detail-label">💭 About Me</span>
                        <span className="detail-value description">{currentMatch.description}</span>
                      </div>
                    )}
                  </div>

                  <div className="match-actions">
                    <button 
                      className="btn-secondary" 
                      onClick={() => viewProfile(currentMatch)}
                    >
                      👤 View Profile
                    </button>
                    <button 
                      className="btn-primary" 
                      onClick={() => expressInterest(currentMatch)}
                    >
                      💕 I'm Interested
                    </button>
                  </div>

                  <div className="match-navigation">
                    <button 
                      className="nav-btn"
                      onClick={() => setCurrentMatchIndex(Math.max(0, currentMatchIndex - 1))}
                      disabled={currentMatchIndex === 0}
                    >
                      ⬅ Previous
                    </button>
                    <span className="match-counter">
                      {currentMatchIndex + 1} of {allMatches.length}
                    </span>
                    <button 
                      className="nav-btn"
                      onClick={() => setCurrentMatchIndex(Math.min(allMatches.length - 1, currentMatchIndex + 1))}
                      disabled={currentMatchIndex === allMatches.length - 1}
                    >
                      Next ➡
                    </button>
                  </div>
                </div>
              ) : (
                <div className="empty-state">
                  <div className="empty-icon">🔍</div>
                  <h2>No Matches Found</h2>
                  <p>Update your preferences to find more matches</p>
                  <button className="btn-primary" onClick={() => setActiveTab('discover')}>
                    Refresh
                  </button>
                </div>
              )}
            </div>
          )}

          {/* ===== MATCHES TAB ===== */}
          {activeTab === 'matches' && (
            <div className="matches-container">
              {hasMyMatches ? (
                <div className="matches-grid">
                  {myMatches.map((match) => (
                    <div key={match.id} className="match-item">
                      <div className="match-avatar">{match.name?.charAt(0) || '?'}</div>
                      <div className="match-info">
                        <h4>{match.name}</h4>
                        <p>{match.age} years • {match.town}</p>
                        <span className="match-status">✅ Accepted</span>
                      </div>
                      <button 
                        className="btn-chat" 
                        onClick={() => startChat(match)}
                      >
                        💬
                      </button>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="empty-state">
                  <div className="empty-icon">💕</div>
                  <h2>No Matches Yet</h2>
                  <p>Start discovering and accepting requests</p>
                  <button className="btn-primary" onClick={() => setActiveTab('discover')}>
                    Discover People
                  </button>
                </div>
              )}
            </div>
          )}

          {/* ===== REQUESTS TAB ===== */}
          {activeTab === 'requests' && (
            <div className="requests-container">
              {hasRequests ? (
                <div className="requests-list">
                  {incomingRequests.map((request) => (
                    <div key={request.id} className="request-item">
                      <div className="request-info">
                        <div className="request-avatar">{request.name?.charAt(0) || '?'}</div>
                        <div>
                          <h4>{request.name}</h4>
                          <p>{request.age} years • {request.town}</p>
                          <p className="request-message">💕 {request.message}</p>
                        </div>
                      </div>
                      <div className="request-actions">
                        <button 
                          className="btn-accept" 
                          onClick={() => acceptRequest(request)}
                        >
                          ✅ Accept
                        </button>
                        <button 
                          className="btn-decline" 
                          onClick={() => declineRequest(request)}
                        >
                          ❌ Decline
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="empty-state">
                  <div className="empty-icon">📬</div>
                  <h2>No Requests</h2>
                  <p>When someone shows interest, you'll see it here</p>
                </div>
              )}
            </div>
          )}

          {/* ===== CHAT TAB ===== */}
          {activeTab === 'chat' && (
            <div className="chat-container">
              {/* Chat Header */}
              <div className="chat-header">
                <h3>💬 {activeChatUser ? `Chat with ${activeChatUser.name}` : 'Messages'}</h3>
                {activeChatUser && (
                  <button className="btn-close-chat" onClick={() => setActiveChatUser(null)}>✕</button>
                )}
              </div>

              {/* Chat Messages */}
              <div className="chat-messages">
                {chatMessages.length === 0 ? (
                  <div className="empty-state">
                    <div className="empty-icon">💬</div>
                    <h3>No Messages</h3>
                    <p>Start a conversation with your matches</p>
                  </div>
                ) : (
                  chatMessages.map((msg) => (
                    <div key={msg.id} className={`message ${msg.isMine ? 'sent' : 'received'}`}>
                      <p>{msg.message}</p>
                      <span className="message-time">{msg.time}</span>
                    </div>
                  ))
                )}
              </div>

              {/* Chat Input */}
              <div className="chat-input">
                <input
                  type="text"
                  value={newMessage}
                  onChange={(e) => setNewMessage(e.target.value)}
                  placeholder="Type a message..."
                  onKeyPress={(e) => {
                    if (e.key === 'Enter') {
                      sendMessage();
                    }
                  }}
                />
                <button className="btn-send" onClick={sendMessage}>
                  Send
                </button>
              </div>
            </div>
          )}

        </main>

        {/* ===== MODALS ===== */}
        {showMatchDetails && selectedMatch && (
          <div className="modal-overlay" onClick={() => setShowMatchDetails(false)}>
            <div className="modal-content" onClick={(e) => e.stopPropagation()}>
              <button className="modal-close" onClick={() => setShowMatchDetails(false)}>✕</button>

              <div className="profile-header">
                <div className="profile-avatar">{selectedMatch.name?.charAt(0) || '?'}</div>
                <h2>{selectedMatch.name}</h2>
                <p>{selectedMatch.age} years • {selectedMatch.town}</p>
              </div>

              <div className="profile-details">
                <div className="profile-item"><span className="label">📞 Phone</span><span>{selectedMatch.phone}</span></div>
                <div className="profile-item"><span className="label">💼 Profession</span><span>{selectedMatch.profession || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">🎓 Education</span><span>{selectedMatch.education || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">💍 Marital Status</span><span>{selectedMatch.marital_status || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">🙏 Religion</span><span>{selectedMatch.religion || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">🌍 Ethnicity</span><span>{selectedMatch.ethnicity || 'Not specified'}</span></div>
                {selectedMatch.description && (
                  <div className="profile-item full-width">
                    <span className="label">💭 About Me</span>
                    <span>{selectedMatch.description}</span>
                  </div>
                )}
              </div>

              <div className="modal-actions">
                <button className="btn-secondary" onClick={() => setShowMatchDetails(false)}>Close</button>
                <button 
                  className="btn-primary" 
                  onClick={() => {
                    expressInterest(selectedMatch);
                    setShowMatchDetails(false);
                  }}
                >
                  💕 Express Interest
                </button>
              </div>
            </div>
          </div>
        )}

        {/* User Profile Modal */}
        {showProfile && currentUser && (
          <div className="modal-overlay" onClick={() => setShowProfile(false)}>
            <div className="modal-content" onClick={(e) => e.stopPropagation()}>
              <button className="modal-close" onClick={() => setShowProfile(false)}>✕</button>

              <div className="profile-header">
                <div className="profile-avatar">{currentUser.name?.charAt(0) || '?'}</div>
                <h2>{currentUser.name}</h2>
                <p>{currentUser.age || '?'} years • {currentUser.town || 'Unknown'}</p>
              </div>

              <div className="profile-details">
                <div className="profile-item"><span className="label">📞 Phone</span><span>{currentUser.phone}</span></div>
                <div className="profile-item"><span className="label">💼 Profession</span><span>{currentUser.profession || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">🎓 Education</span><span>{currentUser.education || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">💍 Marital Status</span><span>{currentUser.marital_status || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">🙏 Religion</span><span>{currentUser.religion || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">🌍 Ethnicity</span><span>{currentUser.ethnicity || 'Not specified'}</span></div>
                {currentUser.description && (
                  <div className="profile-item full-width">
                    <span className="label">💭 About Me</span>
                    <span>{currentUser.description}</span>
                  </div>
                )}
              </div>

              <button className="btn-primary full-width" onClick={() => setShowProfile(false)}>
                Close Profile
              </button>
            </div>
          </div>
        )}
      </div>
    );
  };

  // ============================================
  // MAIN RETURN
  // ============================================

  return (
    <div className="app">
      {renderNotifications()}
      {isLoggedIn ? renderDashboard() : renderRegistration()}
    </div>
  );
}

export default App;
